dictIntegrity.sContent:
"""Integrity tests generated by vaibify."""
# vaibify-template-hash: a0b0edd935351486

import json
import os
import pathlib

import numpy as np
import pytest

try:
    import h5py
except ImportError:
    h5py = None

try:
    import csv as csvModule
except ImportError:
    csvModule = None


def _fdictLoadIntegrityStandards():
    """Load the integrity standards JSON file."""
    # The standards file carries the SAME step suffix as this test
    # file ("test_integrity_<step>.py" pairs with
    # "integrity_standards_<step>.json"), derived from __file__ so
    # one template serves suffixed and legacy fixed names alike.
    sSuffix = pathlib.Path(__file__).stem[len("test_integrity"):]
    sJsonPath = str(
        pathlib.Path(__file__).parent
        / ("integrity_standards" + sSuffix + ".json")
    )
    with open(sJsonPath, encoding="utf-8") as fileHandle:
        return json.load(fileHandle)


_DICT_STANDARDS = _fdictLoadIntegrityStandards()
_LIST_STANDARDS = _DICT_STANDARDS["listStandards"]
_STEP_DIRECTORY = str(pathlib.Path(__file__).parent.parent)


def _fnCheckFileExists(sFullPath):
    """Assert the file exists and is non-empty."""
    assert os.path.isfile(sFullPath), f"File not found: {sFullPath}"
    assert os.path.getsize(sFullPath) > 0, f"File is empty: {sFullPath}"


def _fnCheckShape(daData, tExpectedShape, sFullPath):
    """Assert the data array shape matches the expected shape."""
    if tExpectedShape is not None:
        assert list(daData.shape) == tExpectedShape, (
            f"{sFullPath}: expected shape {tExpectedShape}, "
            f"got {list(daData.shape)}"
        )


def _fnCheckNanInf(daData, bCheckNaN, bCheckInf, sFullPath):
    """Assert no NaN or Inf values in numeric data."""
    if not np.issubdtype(daData.dtype, np.number):
        return
    if bCheckNaN:
        assert not np.any(np.isnan(daData)), (
            f"{sFullPath}: contains NaN values"
        )
    if bCheckInf:
        assert not np.any(np.isinf(daData)), (
            f"{sFullPath}: contains Inf values"
        )


def _fnCheckNpy(sFullPath, dictStandard):
    """Validate a numpy .npy file."""
    daData = np.load(sFullPath, allow_pickle=False)
    tShape = dictStandard.get("tExpectedShape")
    _fnCheckShape(daData, tShape, sFullPath)
    _fnCheckNanInf(
        daData, dictStandard.get("bCheckNaN", False),
        dictStandard.get("bCheckInf", False), sFullPath,
    )


def _fnCheckNpz(sFullPath, dictStandard):
    """Validate a numpy .npz archive."""
    archiveNpz = np.load(sFullPath, allow_pickle=False)
    assert len(archiveNpz.files) > 0, f"{sFullPath}: empty npz archive"
    for sKey in archiveNpz.files:
        daData = archiveNpz[sKey]
        if np.issubdtype(daData.dtype, np.number):
            _fnCheckNanInf(
                daData, dictStandard.get("bCheckNaN", False),
                dictStandard.get("bCheckInf", False), sFullPath,
            )


def _fnCheckCsv(sFullPath, dictStandard):
    """Validate a CSV file."""
    import csv
    with open(sFullPath, newline="", encoding="utf-8") as fileHandle:
        listRows = list(csv.DictReader(fileHandle))
    tShape = dictStandard.get("tExpectedShape")
    if tShape is not None and len(tShape) >= 1:
        assert len(listRows) == tShape[0], (
            f"{sFullPath}: expected {tShape[0]} rows, got {len(listRows)}"
        )
    if dictStandard.get("bCheckNaN", False):
        for dictRow in listRows:
            for sVal in dictRow.values():
                try:
                    fVal = float(sVal)
                    assert not np.isnan(fVal), (
                        f"{sFullPath}: contains NaN"
                    )
                    if dictStandard.get("bCheckInf", False):
                        assert not np.isinf(fVal), (
                            f"{sFullPath}: contains Inf"
                        )
                except ValueError:
                    pass


def _fnCheckJson(sFullPath, dictStandard):
    """Validate a JSON file."""
    with open(sFullPath, encoding="utf-8") as fileHandle:
        json.load(fileHandle)


def _fnCheckHdf5(sFullPath, dictStandard):
    """Validate an HDF5 file."""
    assert h5py is not None, "h5py is not installed"
    with h5py.File(sFullPath, "r") as fileHandle:
        assert len(fileHandle.keys()) > 0, f"{sFullPath}: empty HDF5 file"
        if dictStandard.get("bCheckNaN", False):
            def fnCheckDataset(sName, obj):
                if isinstance(obj, h5py.Dataset):
                    daData = np.array(obj)
                    if np.issubdtype(daData.dtype, np.number):
                        _fnCheckNanInf(
                            daData, True,
                            dictStandard.get("bCheckInf", False),
                            sFullPath,
                        )
            fileHandle.visititems(fnCheckDataset)


def _fnCheckWhitespace(sFullPath, dictStandard):
    """Validate a whitespace-delimited file."""
    with open(sFullPath, encoding="utf-8") as fileHandle:
        listRows = [
            s for s in fileHandle if s.strip()
            and not s.strip().startswith("#")
        ]
    tShape = dictStandard.get("tExpectedShape")
    if tShape is not None and len(tShape) >= 1:
        assert len(listRows) >= tShape[0], (
            f"{sFullPath}: expected >= {tShape[0]} rows"
        )
    if dictStandard.get("bCheckNaN", False):
        for sLine in listRows:
            for sToken in sLine.split():
                try:
                    fVal = float(sToken)
                    assert not np.isnan(fVal)
                    if dictStandard.get("bCheckInf", False):
                        assert not np.isinf(fVal)
                except ValueError:
                    pass


def _fnCheckKeyvalue(sFullPath, dictStandard):
    """Validate a key=value text file."""
    with open(sFullPath, encoding="utf-8") as fileHandle:
        listLines = [s for s in fileHandle if "=" in s]
    assert len(listLines) > 0, f"{sFullPath}: no key=value pairs"


def _fnCheckJsonl(sFullPath, dictStandard):
    """Validate a JSON Lines file."""
    import json as jsonMod
    with open(sFullPath, encoding="utf-8") as fileHandle:
        listRecords = [jsonMod.loads(s) for s in fileHandle if s.strip()]
    assert len(listRecords) > 0, f"{sFullPath}: empty JSONL"


def _fnCheckGenericText(sFullPath, dictStandard):
    """Validate a generic text file by checking it is non-empty."""
    with open(sFullPath, encoding="utf-8") as fileHandle:
        sContent = fileHandle.read()
    assert len(sContent.strip()) > 0, f"{sFullPath}: empty file"


_DICT_INTEGRITY_CHECKERS = {
    "npy": _fnCheckNpy,
    "npz": _fnCheckNpz,
    "csv": _fnCheckCsv,
    "json": _fnCheckJson,
    "hdf5": _fnCheckHdf5,
    "whitespace": _fnCheckWhitespace,
    "keyvalue": _fnCheckKeyvalue,
    "jsonl": _fnCheckJsonl,
}


def _fnDispatchIntegrityCheck(sFullPath, dictStandard):
    """Load and check the file using the appropriate format checker."""
    sFormat = dictStandard.get("sFormat", "")
    fnChecker = _DICT_INTEGRITY_CHECKERS.get(
        sFormat, _fnCheckGenericText,
    )
    fnChecker(sFullPath, dictStandard)


if not _LIST_STANDARDS:
    def test_no_integrity_outputs():
        """Placeholder when no data files are present."""
        assert True
else:
    @pytest.mark.parametrize(
        "dictStandard",
        _LIST_STANDARDS,
        ids=[s["sFileName"] for s in _LIST_STANDARDS],
    )
    def test_integrity_check(dictStandard):
        """Validate structural integrity of a data file."""
        sFullPath = os.path.join(
            _STEP_DIRECTORY, dictStandard["sFileName"],
        )
        _fnCheckFileExists(sFullPath)
        _fnDispatchIntegrityCheck(sFullPath, dictStandard)

dictQuantitative.sContent:
"""Quantitative benchmark tests generated by vaibify."""
# vaibify-template-hash: d51b9f208b37d5b9

import pytest

import json
import pathlib
import re

import numpy as np


_DICT_FORMAT_MAP = {
    ".npy": "npy",
    ".npz": "npz",
    ".json": "json",
    ".csv": "csv",
    ".h5": "hdf5",
    ".hdf5": "hdf5",
    ".dat": "whitespace",
    ".txt": "whitespace",
    ".jsonl": "jsonl",
    ".ndjson": "jsonl",
    ".xlsx": "excel",
    ".xls": "excel",
    ".fits": "fits",
    ".fit": "fits",
    ".mat": "matlab",
    ".parquet": "parquet",
    ".png": "image",
    ".jpg": "image",
    ".jpeg": "image",
    ".tiff": "image",
    ".tif": "image",
    ".fasta": "fasta",
    ".fa": "fasta",
    ".fastq": "fastq",
    ".fq": "fastq",
    ".vcf": "vcf",
    ".bed": "bed",
    ".gff": "gff",
    ".gtf": "gff",
    ".gff3": "gff",
    ".sam": "sam",
    ".log": "syslog",
    ".cef": "cef",
    ".bam": "bam",
    ".unf": "fortran",
    ".sav": "spss",
    ".dta": "stata",
    ".sas7bdat": "sas",
    ".rds": "rdata",
    ".rdata": "rdata",  # lower-cased lookup; ".RData" would never hit
    ".rda": "rdata",
    ".vot": "votable",
    ".ipac": "ipac",
    ".pcap": "pcap",
    ".pcapng": "pcap",
    ".vtk": "vtk",
    ".vtu": "vtk",
    ".cgns": "cgns",
    ".safetensors": "safetensors",
    ".tfrecord": "tfrecord",
}


def _fsInferFormat(sFullPath):
    """Infer the data format from the file extension."""
    sExtension = pathlib.Path(sFullPath).suffix.lower()
    return _DICT_FORMAT_MAP.get(sExtension, None)


def _fnParseAccessSimpleFields(sAccessPath, dictResult):
    """Populate key/column/dataset/section/hdu fields from sAccessPath."""
    matchKey = re.match(
        r"key:(.+?)(?:,(?:index|column|dataset|section|hdu):|$)",
        sAccessPath,
    )
    if matchKey:
        dictResult["key"] = matchKey.group(1)
    matchColumn = re.search(r"column:([^,]+)", sAccessPath)
    if matchColumn:
        dictResult["column"] = matchColumn.group(1)
    matchDataset = re.search(r"dataset:([^,]+)", sAccessPath)
    if matchDataset:
        dictResult["dataset"] = matchDataset.group(1)
    matchSection = re.search(r"section:(\d+)", sAccessPath)
    if matchSection:
        dictResult["iSection"] = int(matchSection.group(1))
    matchHdu = re.search(r"hdu:(\d+)", sAccessPath)
    if matchHdu:
        dictResult["iHdu"] = int(matchHdu.group(1))


def _fnParseAccessIndexField(sAccessPath, dictResult):
    """Populate sAggregate or listIndices from the index: token."""
    matchAggregate = re.search(
        r"index:(mean|min|max|std|p25|p50|p75|p95|p5)\b",
        sAccessPath,
    )
    if matchAggregate:
        dictResult["sAggregate"] = matchAggregate.group(1)
        return
    matchIndex = re.search(r"index:([-\d,]+)", sAccessPath)
    if matchIndex:
        dictResult["listIndices"] = [
            int(x) for x in matchIndex.group(1).split(",")
            if x.strip()
        ]


def _fdictParseAccessPath(sAccessPath):
    """Parse an access path string into a dict of components.

    The ``key:`` capture is greedy until a recognised ``,index:``,
    ``,column:``, ``,dataset:``, ``,section:``, or ``,hdu:`` boundary
    so JSON keys may themselves contain commas (e.g. vconverge's
    ``"compound,key,name"`` payload format).
    """
    dictResult = {}
    _fnParseAccessSimpleFields(sAccessPath, dictResult)
    _fnParseAccessIndexField(sAccessPath, dictResult)
    return dictResult


_DICT_PERCENTILE_AGGREGATES = {
    "p5": 5, "p25": 25, "p50": 50, "p75": 75, "p95": 95,
}


def _ffApplyAggregate(daData, sAggregate):
    """Return a scalar aggregate (mean/min/max/std/percentile) of daData."""
    if sAggregate == "mean":
        return float(daData.mean())
    if sAggregate == "min":
        return float(daData.min())
    if sAggregate == "max":
        return float(daData.max())
    if sAggregate == "std":
        return float(daData.std(ddof=1))
    if sAggregate in _DICT_PERCENTILE_AGGREGATES:
        return float(np.percentile(
            daData, _DICT_PERCENTILE_AGGREGATES[sAggregate],
        ))
    raise ValueError(f"Unknown aggregate: {sAggregate}")


def _ffExtractArrayValue(daData, dictAccess):
    """Extract a scalar from an array by aggregate or index."""
    if daData.ndim == 0:
        return float(daData)
    sAggregate = dictAccess.get("sAggregate")
    if sAggregate:
        return _ffApplyAggregate(daData, sAggregate)
    listIndices = dictAccess.get("listIndices", [-1])
    if len(listIndices) == 1 and daData.ndim > 1:
        return float(daData.flat[listIndices[0]])
    return float(daData[tuple(listIndices)])


def _ffExtractTabularValue(listHeaders, listRows, dictAccess):
    """Extract a value from parsed tabular data."""
    sColumn = dictAccess.get("column", "")
    if sColumn and listHeaders:
        iCol = listHeaders.index(sColumn)
    else:
        iCol = 0
    sAggregate = dictAccess.get("sAggregate")
    if sAggregate:
        daValues = np.array([float(r[iCol]) for r in listRows])
        return _ffApplyAggregate(daValues, sAggregate)
    listIndices = dictAccess.get("listIndices", [-1])
    iRow = listIndices[0] if listIndices else -1
    return float(listRows[iRow][iCol])


def _ffExtractDataframeValue(dfData, dictAccess, sFullPath=""):
    """Extract a value from a pandas DataFrame."""
    try:
        sColumn = dictAccess.get("column", dfData.columns[0])
        sAggregate = dictAccess.get("sAggregate")
        if sAggregate:
            daValues = dfData[sColumn].astype(float).to_numpy()
            return _ffApplyAggregate(daValues, sAggregate)
        listIndices = dictAccess.get("listIndices", [-1])
        iRow = listIndices[0] if listIndices else -1
        return float(dfData[sColumn].iloc[iRow])
    except (KeyError, IndexError, ValueError, TypeError) as errorCaught:
        raise ValueError(
            f"Failed to access dataframe column in {sFullPath}: {errorCaught}",
        ) from errorCaught


def _ffNavigateJsonValue(dictData, dictAccess):
    """Traverse a parsed JSON structure and return a scalar."""
    sKey = dictAccess.get("key", "")
    listKeys = sKey.split(".") if sKey else []
    value = dictData
    for sSubKey in listKeys:
        if isinstance(value, list):
            value = value[int(sSubKey)]
        else:
            value = value[sSubKey]
    sAggregate = dictAccess.get("sAggregate")
    if sAggregate and isinstance(value, list):
        daArray = np.array(value, dtype=float)
        return _ffApplyAggregate(daArray, sAggregate)
    listIndices = dictAccess.get("listIndices", None)
    if listIndices is not None:
        for iIdx in listIndices:
            value = value[iIdx]
    return float(value)


def _flistFilterDataLines(listLines):
    """Strip blank and comment lines from raw file lines."""
    return [
        s for s in listLines
        if s.strip() and not s.strip().startswith("#")
    ]


def _fbIsNumericToken(sToken):
    """Return True if sToken can be parsed as a float."""
    try:
        float(sToken)
        return True
    except ValueError:
        return False


def _ftSplitHeaderAndData(listDataLines):
    """Detect if first line is header or data."""
    if not listDataLines:
        return ("", [])
    listTokens = listDataLines[0].split()
    bAllNumeric = all(_fbIsNumericToken(s) for s in listTokens)
    if bAllNumeric:
        return ("", listDataLines)
    return (listDataLines[0], listDataLines[1:])


def _ffLoadTabularWithComments(
    sFullPath, dictAccess, sCommentPrefix="##", sHeaderPrefix="#",
):
    """Load a value from a tab-delimited file with comment/header lines."""
    listHeaders = []
    listRows = []
    with open(sFullPath, encoding="utf-8", errors="replace") as fileHandle:
        for sLine in fileHandle:
            if sLine.startswith(sCommentPrefix):
                continue
            if sLine.startswith(sHeaderPrefix) and not listHeaders:
                listHeaders = (
                    sLine.lstrip(sHeaderPrefix).strip().split("\t")
                )
                continue
            listRows.append(sLine.strip().split("\t"))
    return _ffExtractTabularValue(listHeaders, listRows, dictAccess)


def _ffLoadNumpyValue(sFullPath, dictAccess):
    """Load a value from a numpy file."""
    try:
        daData = np.load(sFullPath, allow_pickle=False)
    except (ValueError, OSError) as errorCaught:
        raise ValueError(
            f"Failed to load {sFullPath} as npy: {errorCaught}",
        ) from errorCaught
    return _ffExtractArrayValue(daData, dictAccess)


def _ffLoadNpzValue(sFullPath, dictAccess):
    """Load a value from a numpy .npz archive."""
    try:
        archiveNpz = np.load(sFullPath, allow_pickle=False)
    except (ValueError, OSError) as errorCaught:
        raise ValueError(
            f"Failed to load {sFullPath} as npz: {errorCaught}",
        ) from errorCaught
    sKey = dictAccess.get("key", list(archiveNpz.files)[0])
    daData = archiveNpz[sKey]
    return _ffExtractArrayValue(daData, dictAccess)


def _ffLoadKeyvalueValue(sFullPath, dictAccess):
    """Load a value from a key = value text file."""
    sTargetKey = dictAccess.get("key", "")
    with open(sFullPath, encoding="utf-8", errors="replace") as fileHandle:
        for sLine in fileHandle:
            sStripped = sLine.strip()
            if not sStripped or sStripped.startswith("#"):
                continue
            if "=" not in sStripped:
                continue
            sKey, sVal = sStripped.split("=", 1)
            if sKey.strip() == sTargetKey:
                return float(sVal.strip())
    raise KeyError(f"Key {sTargetKey!r} not found in {sFullPath}")


def _ffLoadJsonValue(sFullPath, dictAccess):
    """Load a value from a JSON file.

    Tolerates doubly-serialised payloads: when the file's top-level
    JSON is a string (vconverge's ``json.dumps(json.dumps(...))``
    convention), it is parsed a second time before navigation.
    """
    try:
        with open(sFullPath, encoding="utf-8", errors="replace") as fileHandle:
            dictData = json.load(fileHandle)
    except json.JSONDecodeError as errorCaught:
        raise ValueError(
            f"Failed to load {sFullPath} as json: {errorCaught}",
        ) from errorCaught
    if isinstance(dictData, str):
        try:
            dictData = json.loads(dictData)
        except json.JSONDecodeError as errorCaught:
            raise ValueError(
                f"Failed to re-parse doubly-serialised json in "
                f"{sFullPath}: {errorCaught}",
            ) from errorCaught
    try:
        return _ffNavigateJsonValue(dictData, dictAccess)
    except (KeyError, IndexError, TypeError) as errorCaught:
        raise ValueError(
            f"Failed to access json path in {sFullPath}: {errorCaught}",
        ) from errorCaught


def _ffLoadCsvValue(sFullPath, dictAccess):
    """Load a value from a CSV file, streaming when no full pass is needed.

    Aggregates (mean, std, percentiles, ...) need every row and so
    fall back to a single full pass. Index-based access reads only the
    header plus the rows up to the requested index, so a 100k-row file
    accessed at index 99000 never materialises the full table; access
    at -1 still requires walking the file to find the last row, but
    that walk is single-pass and constant-memory.
    """
    import csv
    sColumn = dictAccess.get("column", "")
    sAggregate = dictAccess.get("sAggregate")
    listIndices = dictAccess.get("listIndices", [-1])
    iIndex = listIndices[0] if listIndices else -1
    try:
        if sAggregate and sColumn:
            return _ffLoadCsvAggregate(sFullPath, sColumn, sAggregate)
        return _ffLoadCsvByRowIndex(sFullPath, sColumn, iIndex)
    except (KeyError, IndexError, ValueError) as errorCaught:
        raise ValueError(
            f"Failed to access csv column in {sFullPath}: {errorCaught}",
        ) from errorCaught
    except csv.Error as errorCaught:
        raise ValueError(
            f"Failed to load {sFullPath} as csv: {errorCaught}",
        ) from errorCaught


def _ftOpenCsvReader(sFullPath):
    """Open ``sFullPath`` and return a ``csv.reader`` plus header list.

    The reader is positioned past the header so the caller iterates
    only over data rows. Returns ``(reader, fileHandle, listHeaders)``
    so the caller can close the file when done.
    """
    import csv
    fileHandle = open(
        sFullPath, newline="", encoding="utf-8", errors="replace",
    )
    reader = csv.reader(fileHandle)
    try:
        listHeaders = next(reader)
    except StopIteration:
        listHeaders = []
    return reader, fileHandle, listHeaders


def _ffLoadCsvAggregate(sFullPath, sColumn, sAggregate):
    """Compute an aggregate over one CSV column with a single streaming pass."""
    reader, fileHandle, listHeaders = _ftOpenCsvReader(sFullPath)
    try:
        iCol = _fiColumnIndexOrRaise(listHeaders, sColumn)
        listValues = [float(listRow[iCol]) for listRow in reader]
    finally:
        fileHandle.close()
    return _ffApplyAggregate(np.array(listValues), sAggregate)


def _ffLoadCsvByRowIndex(sFullPath, sColumn, iIndex):
    """Stream a CSV and return a single cell at the requested row index."""
    if iIndex < 0:
        return _ffLoadCsvNegativeRow(sFullPath, sColumn, iIndex)
    reader, fileHandle, listHeaders = _ftOpenCsvReader(sFullPath)
    try:
        iCol = _fiColumnIndexOrRaise(listHeaders, sColumn)
        for iCurrent, listRow in enumerate(reader):
            if iCurrent == iIndex:
                return float(listRow[iCol])
    finally:
        fileHandle.close()
    raise IndexError(f"CSV row {iIndex} out of range")


def _ffLoadCsvNegativeRow(sFullPath, sColumn, iIndex):
    """Return a CSV cell at a negative row index with constant-memory tail."""
    from collections import deque
    reader, fileHandle, listHeaders = _ftOpenCsvReader(sFullPath)
    try:
        iCol = _fiColumnIndexOrRaise(listHeaders, sColumn)
        dequeTail = deque(reader, maxlen=-iIndex)
    finally:
        fileHandle.close()
    if len(dequeTail) < -iIndex:
        raise IndexError(f"CSV row {iIndex} out of range")
    return float(dequeTail[0][iCol])


def _fiColumnIndexOrRaise(listHeaders, sColumn):
    """Return the integer index of ``sColumn`` in ``listHeaders``.

    Mirrors the historical ``DictReader``-based loader's behaviour:
    accessing a non-existent column raises ``KeyError``; an empty
    ``sColumn`` raises ``KeyError`` too because the legacy code did
    ``row[""]`` which keys into a missing label.
    """
    if not sColumn:
        raise KeyError("CSV column name required")
    try:
        return listHeaders.index(sColumn)
    except ValueError:
        raise KeyError(sColumn)


def _ffLoadHdf5Value(sFullPath, dictAccess):
    """Load a value from an HDF5 file using h5py native slice indexing.

    For datasets that hold MB-to-GB of values, materialising the whole
    array with ``np.array(fileHdf5[sDataset])`` is fatal: a 4 GB chunked
    dataset becomes 4 GB of host RAM just to return one scalar. h5py's
    native slice indexing (``fileHdf5[sDataset][tuple(...)]``) reads
    only the requested chunk(s) from disk, so cost scales with the
    answer, not the file. Aggregates still need the full array so they
    take the legacy ``np.array`` path.
    """
    import h5py
    sDataset = dictAccess.get("dataset", "")
    try:
        with h5py.File(sFullPath, "r") as fileHdf5:
            datasetHdf5 = fileHdf5[sDataset]
            return _ffExtractHdf5Value(datasetHdf5, dictAccess)
    except (OSError, KeyError) as errorCaught:
        raise ValueError(
            f"Failed to load {sFullPath} as hdf5: {errorCaught}",
        ) from errorCaught


def _ffExtractHdf5Value(datasetHdf5, dictAccess):
    """Extract a scalar from an h5py dataset, slicing lazily when possible."""
    if datasetHdf5.ndim == 0:
        return float(datasetHdf5[()])
    sAggregate = dictAccess.get("sAggregate")
    if sAggregate:
        return _ffApplyAggregate(np.array(datasetHdf5), sAggregate)
    listIndices = dictAccess.get("listIndices", [-1])
    if len(listIndices) == 1 and datasetHdf5.ndim > 1:
        tShape = datasetHdf5.shape
        iFlat = listIndices[0]
        if iFlat < 0:
            iFlat += int(np.prod(tShape))
        tIndex = np.unravel_index(iFlat, tShape)
        return float(datasetHdf5[tIndex])
    return float(datasetHdf5[tuple(listIndices)])


def _ffLoadWhitespaceValue(sFullPath, dictAccess):
    """Load a value from a whitespace-delimited text file."""
    sColumn = dictAccess.get("column", "")
    listIndices = dictAccess.get("listIndices", [-1])
    iIndex = listIndices[0] if listIndices else -1
    try:
        with open(sFullPath, encoding="utf-8", errors="replace") as fileHandle:
            listRawLines = fileHandle.readlines()
    except OSError as errorCaught:
        raise ValueError(
            f"Failed to load {sFullPath} as whitespace: {errorCaught}",
        ) from errorCaught
    listDataLines = _flistFilterDataLines(listRawLines)
    sHeader, listDataRows = _ftSplitHeaderAndData(listDataLines)
    listColumns = sHeader.split() if sHeader else []
    listRows = [sRow.split() for sRow in listDataRows]
    try:
        if sColumn and listColumns:
            iColumn = listColumns.index(sColumn)
        else:
            iColumn = listIndices[1] if len(listIndices) > 1 else 0
    except ValueError as errorCaught:
        raise ValueError(
            f"Column {sColumn!r} not found in {sFullPath}",
        ) from errorCaught
    sAggregate = dictAccess.get("sAggregate")
    if sAggregate:
        daValues = np.array([float(r[iColumn]) for r in listRows])
        return _ffApplyAggregate(daValues, sAggregate)
    return float(listRows[iIndex][iColumn])


def _ffLoadJsonlValue(sFullPath, dictAccess):
    """Load a value from a JSON Lines file."""
    try:
        with open(sFullPath, encoding="utf-8", errors="replace") as fileHandle:
            listRecords = [
                json.loads(sLine) for sLine in fileHandle if sLine.strip()
            ]
    except json.JSONDecodeError as errorCaught:
        raise ValueError(
            f"Failed to load {sFullPath} as jsonl: {errorCaught}",
        ) from errorCaught
    sKey = dictAccess.get("key", "")
    sAggregate = dictAccess.get("sAggregate")
    try:
        if sAggregate and sKey:
            daValues = np.array([float(r[sKey]) for r in listRecords])
            return _ffApplyAggregate(daValues, sAggregate)
        listIndices = dictAccess.get("listIndices", [0])
        iRow = listIndices[0] if listIndices else 0
        if sKey:
            return float(listRecords[iRow][sKey])
        return float(listRecords[iRow])
    except (KeyError, IndexError, TypeError) as errorCaught:
        raise ValueError(
            f"Failed to access jsonl data in {sFullPath}: {errorCaught}",
        ) from errorCaught


def _ffLoadExcelValue(sFullPath, dictAccess):
    """Load a value from an Excel file."""
    try:
        import openpyxl
    except ImportError:
        raise ImportError("openpyxl is required to load Excel files")
    try:
        workbook = openpyxl.load_workbook(sFullPath, read_only=True)
        sheet = workbook.active
        listRows = list(sheet.iter_rows(values_only=True))
        workbook.close()
    except Exception as errorCaught:
        raise ValueError(
            f"Failed to load {sFullPath} as excel: {errorCaught}",
        ) from errorCaught
    try:
        listHeaders = [
            str(c) if c else f"col{i}"
            for i, c in enumerate(listRows[0])
        ]
        sColumn = dictAccess.get("column", listHeaders[0])
        iCol = listHeaders.index(sColumn)
        sAggregate = dictAccess.get("sAggregate")
        if sAggregate:
            daValues = np.array([float(r[iCol]) for r in listRows[1:]])
            return _ffApplyAggregate(daValues, sAggregate)
        listIndices = dictAccess.get("listIndices", [-1])
        iRow = listIndices[0] if listIndices else -1
        return float(listRows[1:][iRow][iCol])
    except (KeyError, IndexError, ValueError, TypeError) as errorCaught:
        raise ValueError(
            f"Failed to access excel data in {sFullPath}: {errorCaught}",
        ) from errorCaught


def _ffLoadFitsValue(sFullPath, dictAccess):
    """Load a value from a FITS file."""
    try:
        from astropy.io import fits as fitsLib
    except ImportError:
        raise ImportError("astropy is required to load FITS files")
    iHdu = dictAccess.get("iHdu", 0)
    sAggregate = dictAccess.get("sAggregate")
    sColumn = dictAccess.get("column", "")
    listIndices = dictAccess.get("listIndices", [0])
    try:
        with fitsLib.open(sFullPath) as hduList:
            hdu = hduList[iHdu]
            if hdu.data is None:
                raise ValueError(f"HDU {iHdu} has no data")
            if sColumn and hasattr(hdu, "columns"):
                daData = np.array(hdu.data[sColumn], dtype=float)
            else:
                daData = np.array(hdu.data, dtype=float).flatten()
    except (OSError, KeyError, TypeError, IndexError) as errorCaught:
        raise ValueError(
            f"Failed to load {sFullPath} as fits: {errorCaught}",
        ) from errorCaught
    if sAggregate:
        return _ffApplyAggregate(daData, sAggregate)
    iDataIdx = listIndices[1] if len(listIndices) > 1 else 0
    return float(daData[iDataIdx])


def _ffLoadMatlabValue(sFullPath, dictAccess):
